65	static void
66	si5351_bulk_write(const uint8_t *buf, int len)
67	{
68	  i2cAcquireBus(&I2CD1);
69	  (void)i2cMasterTransmitTimeout(&I2CD1, SI5351_I2C_ADDR, buf, len, NULL, 0, 1000);
70	  i2cReleaseBus(&I2CD1);
71	}
