82	static void si5351_wait_pll_lock(void)
83	{
84	  uint8_t status;
85	  int count = 100;
86	  do{
87	    status=0xFF;
88	    si5351_bulk_read(0, &status, 1);
89	    if ((status & 0x60) == 0) // PLLA and PLLB locked
90	      return;
91	  }while (--count);
92	}
93	#endif
