152	// Reset PLL need then band changes
153	static void si5351_reset_pll(uint8_t mask)
154	{
155	  // Writing a 1<<5 will reset PLLA, 1<<7 reset PLLB, this is a self clearing bits.
156	  // !!! Need delay before reset PLL for apply PLL freq changes before
157	  chThdSleepMicroseconds(DELAY_RESET_PLL);
158	  si5351_write(SI5351_REG_177_PLL_RESET, mask | 0x0C);
159	}
