161	void si5351_disable_output(void)
162	{
163	  si5351_write(SI5351_REG_3_OUTPUT_ENABLE_CONTROL, 0xFF);
164	  si5351_bulk_write(disable_output, sizeof(disable_output));
165	  current_band = 0;
166	}
