168	void si5351_enable_output(void)
169	{
170	  si5351_write(SI5351_REG_3_OUTPUT_ENABLE_CONTROL, ~(SI5351_CLK0_EN|SI5351_CLK1_EN|SI5351_CLK2_EN));
171	//si5351_reset_pll(SI5351_PLL_RESET_A | SI5351_PLL_RESET_B);
172	  current_freq = 0;
173	  current_band = 0;
174	}
