176	// Set PLL freq = XTALFREQ * (mult + num/denom)
177	static void si5351_setupPLL(uint8_t   pllSource,  /* SI5351_REG_PLL_A or SI5351_REG_PLL_B */
178	                            uint32_t  mult,
179	                            uint32_t  num,
180	                            uint32_t  denom)
181	{
182	  /* Feedback Multisynth Divider Equation
183	   * where: a = mult, b = num and c = denom
184	   * P1 register is an 18-bit value using following formula:
185	   *    P1[17:0] = 128 * mult + int((128*num)/denom) - 512
186	   * P2 register is a 20-bit value using the following formula:
187	   *    P2[19:0] = (128 * num) % denom
188	   * P3 register is a 20-bit value using the following formula:
189	   *    P3[19:0] = denom
190	   */
191	  /* Set the main PLL config registers */
192	  mult <<= 7;
193	  num <<= 7;
194	  uint32_t P1 = mult - 512;  // Integer mode
195	  uint32_t P2 = 0;
196	  uint32_t P3 = 1;
197	  if (num) {                 // Fractional mode
198	    P1+= num / denom;
199	    P2 = num % denom;
200	    P3 = denom;
201	  }
202	  // Pll MSN(A|B) registers Datasheet
203	  uint8_t reg[9];
204	  reg[0] = pllSource;                                       // SI5351_REG_PLL_A or SI5351_REG_PLL_B
205	  reg[1] = (P3 & 0x0FF00) >> 8;                             // MSN_P3[15: 8]
206	  reg[2] = (P3 & 0x000FF);                                  // MSN_P3[ 7: 0]
207	  reg[3] = (P1 & 0x30000) >> 16;                            // MSN_P1[17:16]
208	  reg[4] = (P1 & 0x0FF00) >> 8;                             // MSN_P1[15: 8]
209	  reg[5] = (P1 & 0x000FF);                                  // MSN_P1[ 7: 0]
210	  reg[6] = ((P3 & 0xF0000) >> 12) | ((P2 & 0xF0000) >> 16); // MSN_P3[19:16] | MSN_P2[19:16]
211	  reg[7] = (P2 & 0x0FF00) >> 8;                             // MSN_P2[15: 8]
212	  reg[8] = (P2 & 0x000FF);                                  // MSN_P2[ 7: 0]
213	  si5351_bulk_write(reg, 9);
214	}
215	
216	// Set Multisynth divider = (div + num/denom) * rdiv
217	static void
218	si5351_setupMultisynth(uint8_t   channel,
219	                       uint32_t  div,    // 4,6,8, 8+ ~ 900
220	                       uint32_t  num,
221	                       uint32_t  denom,
222	                       uint32_t  rdiv,   // SI5351_R_DIV_1~128
223	                       uint8_t   chctrl) // SI5351_REG_16_CLKX_CONTROL settings
224	{
225	  /* Output Multisynth Divider Equations
226	   * where: a = div, b = num and c = denom
227	   * P1 register is an 18-bit value using following formula:
228	   *   P1[17:0] = 128 * a + int((128*b)/c) - 512
229	   * P2 register is a 20-bit value using the following formula:
230	   *   P2[19:0] = (128 * b) % c
231	   * P3 register is a 20-bit value using the following formula:
232	   *   P3[19:0] = c
233	   */
234	  /* Set the main PLL config registers */
235	  uint32_t P1 = 0;
236	  uint32_t P2 = 0;
237	  uint32_t P3 = 1;
238	  if (div == 4)
239	    rdiv|= SI5351_DIVBY4;
240	  else {
241	    num<<=7;
242	    div<<=7;
243	    P1 = div - 512; // Integer mode
244	    if (num) {       // Fractional mode
245	      P1+= num / denom;
246	      P2 = num % denom;
247	      P3 = denom;
248	    }
249	  }
250	  /* Set the MSx config registers */
251	  uint8_t reg[9];
252	  reg[0] = msreg_base[channel];                       // SI5351_REG_42_MULTISYNTH0, SI5351_REG_50_MULTISYNTH1, SI5351_REG_58_MULTISYNTH2
253	  reg[1] = (P3 & 0x0FF00)>>8;                         // MSx_P3[15: 8]
254	  reg[2] = (P3 & 0x000FF);                            // MSx_P3[ 7: 0]
255	  reg[3] = ((P1 & 0x30000)>>16)| rdiv;                // Rx_DIV[2:0] | MSx_DIVBY4[1:0] | MSx_P1[17:16]
256	  reg[4] = (P1 & 0x0FF00)>> 8;                        // MSx_P1[15: 8]
257	  reg[5] = (P1 & 0x000FF);                            // MSx_P1[ 7: 0]
258	  reg[6] = ((P3 & 0xF0000)>>12)|((P2 & 0xF0000)>>16); // MSx_P3[19:16] | MSx_P2[19:16]
259	  reg[7] = (P2 & 0x0FF00)>>8;                         // MSx_P2[15: 8]
260	  reg[8] = (P2 & 0x000FF);                            // MSx_P2[ 7: 0]
261	  si5351_bulk_write(reg, 9);
262	
263	  /* Configure the clk control and enable the output */
264	  uint8_t dat = chctrl | SI5351_CLK_INPUT_MULTISYNTH_N;
265	  if (num == 0)
266	    dat |= SI5351_CLK_INTEGER_MODE;
267	
268	#if USE_CLK_CONTROL_CACHE == TRUE
269	  // Use cache for this reg, not update if not change
270	  static uint8_t clk_cache[3];
271	  if (clk_cache[channel]!=dat) {
272	    si5351_write(clkctrl[channel], dat);
273	    clk_cache[channel]=dat;
274	  }
275	#else
276	  si5351_write(clkctrl[channel], dat);
277	#endif
278	}
