280	// Find better approximate values for n/d
281	#define MAX_DENOMINATOR ((1 << 20) - 1)
282	static inline void approximate_fraction(uint32_t *n, uint32_t *d)
283	{
284	  // cf. https://github.com/python/cpython/blob/master/Lib/fractions.py#L227
285	  uint32_t denom = *d;
286	  if (denom > MAX_DENOMINATOR) {
287	    uint32_t num = *n;
288	    uint32_t p0 = 0, q0 = 1, p1 = 1, q1 = 0;
289	    while (denom != 0) {
290	      uint32_t a = num / denom;
291	      uint32_t b = num % denom;
292	      uint32_t q2 = q0 + a*q1;
293	      if (q2 > MAX_DENOMINATOR)
294	        break;
295	      uint32_t p2 = p0 + a*p1;
296	      p0 = p1; q0 = q1; p1 = p2; q1 = q2;
297	      num = denom; denom = b;
298	    }
299	    *n = p1;
300	    *d = q1;
301	  }
302	}
303	
304	// Setup Multisynth divider for get correct output freq if fixed PLL = pllfreq
305	static void
306	si5351_set_frequency_fixedpll(uint8_t channel, uint64_t pllfreq, uint32_t freq, uint32_t rdiv, uint8_t chctrl)
307	{
308	  uint32_t denom = freq;
309	  uint32_t div = pllfreq / denom; // range: 8 ~ 1800
310	  uint32_t num = pllfreq % denom;
311	  approximate_fraction(&num, &denom);
312	  si5351_setupMultisynth(channel, div, num, denom, rdiv, chctrl);
313	}
314	
315	// Setup PLL freq if Multisynth divider fixed = div (need get output =  freq/mul)
316	static void
317	si5351_setupPLL_freq(uint32_t pllSource, uint32_t freq, uint32_t div, uint32_t mul)
318	{
319	  uint32_t denom = XTALFREQ * mul;
320	  uint64_t pllfreq = (uint64_t)freq * div;
321	  uint32_t multi = pllfreq / denom;
322	  uint32_t num   = pllfreq % denom;
323	  approximate_fraction(&num, &denom);
324	  si5351_setupPLL(pllSource, multi, num, denom);
325	}
