336	void
337	si5351_set_frequency(int channel, uint32_t freq, uint8_t drive_strength)
338	{
339	  if (freq <= 100000000) {
340	    si5351_setupPLL(SI5351_PLL_B, 32, 0, 1);
341	    si5351_set_frequency_fixedpll(channel, SI5351_PLL_B, PLLFREQ, freq, SI5351_R_DIV_1, drive_strength, 1);
342	  } else if (freq < 150000000) {
343	    si5351_set_frequency_fixeddiv(channel, SI5351_PLL_B, freq, 6, drive_strength, 1);
344	  } else {
345	    si5351_set_frequency_fixeddiv(channel, SI5351_PLL_B, freq, 4, drive_strength, 1);
346	  }
347	}
348	#endif
