350	/*
351	 * Frequency generation divide on 3 band
352	 *  Band 1
353	 *   1~100MHz      fixed PLL = XTALFREQ * PLL_N, fractional divider
354	 *  Band 2
355	 * 100~150MHz fractional PLL = 600- 900MHz, fixed divider 'fdiv = 6'
356	 *  Band 3
357	 * 150~300MHz fractional PLL = 600-1200MHz, fixed divider 'fdiv = 4'
358	 *
359	 * For FREQ_HARMONICS = 300MHz - band range is:
360	 *  +-----------------------------------------------------------------------------------------------------------------------+
361	 *  |     Band 1      |   Band 2     |    Band 3    |   Band 2     |                       Band 3                           |
362	 *  +-----------------------------------------------------------------------------------------------------------------------+
363	 *  |            Direct mode  x1 :  x1              |           x3 : x5         |    x5-x7    |    x7-x9     |    x9-x11    |
364	 *  +-----------------------------------------------------------------------------------------------------------------------+
365	 *  | 50kHz - 100MHz  | 100 - 150MHz | 150 - 300MHz |  300-450MHz  | 450-900MHz | 900-1500MHz | 1500-2100MHz | 2100-2700MHz |
366	 *  +-----------------------------------------------------------------------------------------------------------------------+
367	 *  |              f = 50kHz-300MHz                 | f=100-150    | f=150-300  | f=150-300   | f=214-300    | f=233-300    |
368	 *  |             of = 50kHz-300MHz                 |of= 60- 90    |of= 90-180  |of=128-215   |of=166-234    |of=190-246    |
369	 *  +-----------------------------------------------------------------------------------------------------------------------+
370	 */
371	static inline uint8_t
372	si5351_get_band(uint32_t freq)
373	{
374	  if (freq < 100000000U) return 1;
375	  if (freq < 150000000U) return 2;
376	  return 3;
377	}
378	
379	/*
380	 * Maximum supported frequency = FREQ_HARMONICS * 9U
381	 * configure output as follows:
382	 * CLK0: frequency + offset
383	 * CLK1: frequency
384	 * CLK2: fixed 8MHz
385	 */
386	int
387	si5351_set_frequency(uint32_t freq, uint8_t drive_strength)
388	{
389	  uint8_t band;
390	  int delay = DELAY_NORMAL;
391	  if (freq == current_freq)
392	    return delay;
393	  else if (current_freq > freq)  // Reset band on sweep begin (if set range 150-600, fix error then 600 MHz band 2 or 3 go back)
394	    current_band = 0;
395	  current_freq = freq;
396	  uint32_t ofreq = freq + current_offset;
397	  uint32_t mul = 1, omul = 1;
398	  uint32_t rdiv = SI5351_R_DIV_1;
399	  uint32_t fdiv;
400	  // Fix possible incorrect input
401	  drive_strength&=SI5351_CLK_DRIVE_STRENGTH_MASK;
402	
403	  if (freq >= config.harmonic_freq_threshold * 7U) {
404	     mul =  9;
405	    omul = 11;
406	  } else if (freq >= config.harmonic_freq_threshold * 5U) {
407	     mul = 7;
408	    omul = 9;
409	  } else if (freq >= config.harmonic_freq_threshold * 3U) {
410	     mul = 5;
411	    omul = 7;
412	  } else if (freq >= config.harmonic_freq_threshold) {
413	     mul = 3;
414	    omul = 5;
415	  } else if (freq <= 500000U) {
416	    rdiv = SI5351_R_DIV_64;
417	     freq<<= 6;
418	    ofreq<<= 6;
419	  } else if (freq <= 4000000U) {
420	    rdiv = SI5351_R_DIV_8;
421	     freq<<= 3;
422	    ofreq<<= 3;
423	  }
424	  band = si5351_get_band(freq / mul);
425	  switch (band) {
426	    case 1:
427	      // Setup CH0 and CH1 constant PLLA freq at band change, and set CH2 freq =
428	      // CLK2_FREQUENCY
429	      if (current_band != 1) {
430	        si5351_setupPLL(SI5351_REG_PLL_A, PLL_N, 0, 1);
431	        si5351_set_frequency_fixedpll(
432	            2, XTALFREQ * PLL_N, CLK2_FREQUENCY, SI5351_R_DIV_1,
433	            SI5351_CLK_DRIVE_STRENGTH_2MA | SI5351_CLK_PLL_SELECT_A);
434	        delay = DELAY_BANDCHANGE_1;
435	      } else {
436	        delay = DELAY_BAND_1;
437	      }
438	      // Calculate and set CH0 and CH1 divider
439	      si5351_set_frequency_fixedpll(0, (uint64_t)omul * XTALFREQ * PLL_N, ofreq, rdiv,
440	                                    drive_strength | SI5351_CLK_PLL_SELECT_A);
441	      si5351_set_frequency_fixedpll(1, (uint64_t)mul * XTALFREQ * PLL_N, freq, rdiv,
442	                                    drive_strength | SI5351_CLK_PLL_SELECT_A);
443	      break;
444	    case 2:  // fdiv = 6
445	    case 3:  // fdiv = 4;
446	      fdiv = (band == 2) ? 6 : 4;
447	      // Setup CH0 and CH1 constant fdiv divider at change
448	      if (current_band != band) {
449	        si5351_setupMultisynth(0, fdiv, 0, 1, SI5351_R_DIV_1,
450	                               drive_strength | SI5351_CLK_PLL_SELECT_A);
451	        si5351_setupMultisynth(1, fdiv, 0, 1, SI5351_R_DIV_1,
452	                               drive_strength | SI5351_CLK_PLL_SELECT_B);
453	        delay = DELAY_BANDCHANGE_2;
454	      } else {
455	        delay = DELAY_BAND_2;
456	      }
457	      // Calculate and set CH0 and CH1 PLL freq
458	      si5351_setupPLL_freq(SI5351_REG_PLL_A, ofreq, fdiv,
459	                           omul);  // set PLLA freq = (ofreq/omul)*fdiv
460	      si5351_setupPLL_freq(SI5351_REG_PLL_B, freq, fdiv,
461	                           mul);  // set PLLB freq = ( freq/ mul)*fdiv
462	      // Calculate CH2 freq = CLK2_FREQUENCY, depend from calculated before CH1 PLLB = (freq/mul)*fdiv
463	      si5351_set_frequency_fixedpll(
464	          2, (uint64_t)freq * fdiv, CLK2_FREQUENCY * mul, SI5351_R_DIV_1,
465	          SI5351_CLK_DRIVE_STRENGTH_2MA | SI5351_CLK_PLL_SELECT_B);
466	      break;
467	  }
468	  if (current_band != band) {
469	    si5351_reset_pll(SI5351_PLL_RESET_A|SI5351_PLL_RESET_B);
470	    current_band = band;
471	  }
472	  return delay;
473	}
